trazabilidad_archivos.codigo_final:
*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

:root {
  /* === TOKENS: COLORES DE MARCA === */
  --color-primary: #0d0d0d;
  --color-secondary: #c9a84c;
  --color-bg: #f5f5f0;
  --color-bg-alt: #1a1a1a;
  --color-text: #1a1a1a;
  --color-text-muted: #6b6b6b;
  --color-border: #d4d4d4;
  --color-white: #ffffff;
  --color-overlay: rgba(0, 0, 0, 0.55);

  /* === TOKENS: TIPOGRAFÍA === */
  --font-heading: 'Playfair Display', Georgia, serif;
  --font-body: 'Inter', 'Helvetica Neue', Arial, sans-serif;
  --font-size-base: 1rem;
  --font-size-sm: 0.875rem;
  --font-size-lg: 1.125rem;
  --font-size-xl: 1.5rem;
  --font-size-2xl: 2rem;
  --font-size-3xl: 3rem;
  --font-weight-regular: 400;
  --font-weight-medium: 500;
  --font-weight-bold: 700;
  --line-height-tight: 1.2;
  --line-height-base: 1.6;

  /* === TOKENS: ESPACIADO (escala de 8px) === */
  --space-1: 0.25rem;
  --space-2: 0.5rem;
  --space-3: 0.75rem;
  --space-4: 1rem;
  --space-6: 1.5rem;
  --space-8: 2rem;
  --space-12: 3rem;
  --space-16: 4rem;
  --space-24: 6rem;

  /* === TOKENS: LAYOUT === */
  --container-max: 75rem;
  --container-padding: var(--space-6);
  --border-radius-sm: 0.25rem;
  --border-radius-md: 0.5rem;
  --border-radius-lg: 1rem;
  --transition-base: 0.25s ease;
  --shadow-sm: 0 1px 4px rgba(0, 0, 0, 0.08), 0 1px 2px rgba(0, 0, 0, 0.06);
  --shadow-md: 0 4px 16px rgba(0, 0, 0, 0.14), 0 2px 6px rgba(0, 0, 0, 0.08);
  --z-nav: 100;
  --z-overlay: 200;
  --z-modal: 300;
}

/* === RESET === */

html {
  font-size: 100%;
  scroll-behavior: smooth;
}

body {
  font-family: var(--font-body);
  color: var(--color-text);
  background-color: var(--color-bg);
  line-height: var(--line-height-base);
}

img,
video {
  display: block;
  max-width: 100%;
  height: auto;
}

a {
  color: inherit;
  text-decoration: none;
}

button {
  cursor: pointer;
  border: none;
  background: none;
  font: inherit;
}

input,
textarea,
select {
  font: inherit;
  color: inherit;
  background: transparent;
  border: none;
  outline: none;
}

/* === ACCESIBILIDAD === */

.sr-only {
  position: absolute !important;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

/* === TIPOGRAFÍA BASE === */

h1,
h2,
h3,
h4,
h5,
h6 {
  font-family: var(--font-heading);
  font-weight: var(--font-weight-bold);
  line-height: var(--line-height-tight);
  color: var(--color-primary);
}

h1 {
  font-size: var(--font-size-3xl);
}

h2 {
  font-size: var(--font-size-2xl);
}

h3 {
  font-size: var(--font-size-xl);
}

h4 {
  font-size: var(--font-size-lg);
}

h5,
h6 {
  font-size: var(--font-size-base);
}

p {
  font-size: var(--font-size-base);
  line-height: var(--line-height-base);
  color: var(--color-text);
}

small {
  font-size: var(--font-size-sm);
  color: var(--color-text-muted);
}

strong {
  font-weight: var(--font-weight-bold);
}

/* === LAYOUT: CONTENEDOR === */

.container {
  width: 100%;
  max-width: var(--container-max);
  margin-inline: auto;
  padding-inline: var(--container-padding);
}

/* === LAYOUT: GRID Y FLEX UTILITARIOS === */

.grid {
  display: grid;
  gap: var(--space-8);
}

.grid--2 {
  grid-template-columns: repeat(2, 1fr);
}

.grid--3 {
  grid-template-columns: repeat(3, 1fr);
}

.grid--4 {
  grid-template-columns: repeat(4, 1fr);
}

.flex {
  display: flex;
}

.flex--center {
  align-items: center;
  justify-content: center;
}

.flex--between {
  align-items: center;
  justify-content: space-between;
}

.flex--gap {
  gap: var(--space-4);
}

.flex--col {
  flex-direction: column;
}

/* === SECCIÓN BASE === */

.section {
  padding-block: var(--space-24);
}

.section--alt {
  background-color: var(--color-bg-alt);
  color: var(--color-white);
}

.section--alt h1,
.section--alt h2,
.section--alt h3,
.section--alt h4,
.section--alt h5,
.section--alt h6 {
  color: var(--color-white);
}

.section--alt p {
  color: rgba(255, 255, 255, 0.8);
}

.section__header {
  text-align: center;
  margin-bottom: var(--space-16);
}

.section__eyebrow {
  display: block;
  font-size: var(--font-size-sm);
  font-weight: var(--font-weight-medium);
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--color-secondary);
  margin-bottom: var(--space-3);
}

.section__title {
  margin-bottom: var(--space-4);
}

.section__subtitle {
  font-size: var(--font-size-lg);
  color: var(--color-text-muted);
  max-width: 42rem;
  margin-inline: auto;
}

.section--alt .section__subtitle {
  color: rgba(255, 255, 255, 0.65);
}

/* === COMPONENTE: NAVEGACIÓN === */

.nav {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: var(--z-nav);
  background-color: var(--color-primary);
  border-bottom: 1px solid rgba(255, 255, 255, 0.08);
  transition: background-color var(--transition-base), box-shadow var(--transition-base);
}

.nav--scrolled {
  background-color: rgba(13, 13, 13, 0.96);
  box-shadow: var(--shadow-md);
}

.nav__inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 4rem;
}

.nav__logo {
  font-family: var(--font-heading);
  font-size: var(--font-size-xl);
  font-weight: var(--font-weight-bold);
  color: var(--color-white);
  letter-spacing: 0.02em;
  transition: color var(--transition-base);
}

.nav__logo:hover {
  color: var(--color-secondary);
}

.nav__list {
  display: flex;
  align-items: center;
  gap: var(--space-8);
  list-style: none;
}

.nav__link {
  font-size: var(--font-size-sm);
  font-weight: var(--font-weight-medium);
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: rgba(255, 255, 255, 0.75);
  transition: color var(--transition-base);
  position: relative;
}

.nav__link::after {
  content: '';
  position: absolute;
  bottom: -0.25rem;
  left: 0;
  right: 0;
  height: 2px;
  background-color: var(--color-secondary);
  transform: scaleX(0);
  transform-origin: left;
  transition: transform var(--transition-base);
}

.nav__link:hover,
.nav__link--active {
  color: var(--color-white);
}

.nav__link:hover::after,
.nav__link--active::after {
  transform: scaleX(1);
}

.nav__cta {
  font-size: var(--font-size-sm);
  font-weight: var(--font-weight-medium);
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--color-primary);
  background-color: var(--color-secondary);
  padding: var(--space-2) var(--space-6);
  border-radius: var(--border-radius-sm);
  transition: background-color var(--transition-base), transform var(--transition-base);
}

.nav__cta:hover {
  background-color: #b8943e;
  transform: translateY(-1px);
}

.nav__toggle {
  display: none;
  flex-direction: column;
  gap: 5px;
  cursor: pointer;
  padding: var(--space-2);
}

.nav__toggle-bar {
  display: block;
  width: 1.5rem;
  height: 2px;
  background-color: var(--color-white);
  border-radius: 2px;
  transition: transform var(--transition-base), opacity var(--transition-base);
}

.nav__toggle[aria-expanded="true"] .nav__toggle-bar:nth-child(1) {
  transform: translateY(7px) rotate(45deg);
}

.nav__toggle[aria-expanded="true"] .nav__toggle-bar:nth-child(2) {
  opacity: 0;
}

.nav__toggle[aria-expanded="true"] .nav__toggle-bar:nth-child(3) {
  transform: translateY(-7px) rotate(-45deg);
}

/* === COMPONENTE: HERO === */

.hero {
  position: relative;
  min-height: 100svh;
  display: flex;
  align-items: center;
  justify-content: center;
  overflow: hidden;
  background-color: var(--color-primary);
  padding-top: 4rem;
}

.hero__bg {
  position: absolute;
  inset: 0;
  object-fit: cover;
  width: 100%;
  height: 100%;
  opacity: 0.45;
}

.hero__overlay {
  position: absolute;
  inset: 0;
  background-color: var(--color-overlay);
}

.hero__content {
  position: relative;
  z-index: 1;
  text-align: center;
  max-width: 52rem;
  padding-inline: var(--container-padding);
}

.hero__eyebrow {
  display: block;
  font-size: var(--font-size-sm);
  font-weight: var(--font-weight-medium);
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--color-secondary);
  margin-bottom: var(--space-4);
}

.hero__title {
  font-size: clamp(2rem, 6vw, var(--font-size-3xl));
  color: var(--color-white);
  margin-bottom: var(--space-6);
}

.hero__subtitle {
  font-size: var(--font-size-lg);
  color: rgba(255, 255, 255, 0.8);
  margin-bottom: var(--space-12);
  max-width: 36rem;
  margin-inline: auto;
  margin-bottom: var(--space-12);
}

.hero__actions {
  display: flex;
  gap: var(--space-4);
  justify-content: center;
  flex-wrap: wrap;
}

/* === COMPONENTE: BOTONES === */

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: var(--space-2);
  font-family: var(--font-body);
  font-size: var(--font-size-sm);
  font-weight: var(--font-weight-medium);
  letter-spacing: 0.06em;
  text-transform: uppercase;
  padding: var(--space-3) var(--space-8);
  border-radius: var(--border-radius-sm);
  transition: background-color var(--transition-base),
              color var(--transition-base),
              transform var(--transition-base),
              box-shadow var(--transition-base);
  cursor: pointer;
  border: 2px solid transparent;
}

.btn:hover {
  transform: translateY(-2px);
}

.btn:active {
  transform: translateY(0);
}

.btn--primary {
  background-color: var(--color-secondary);
  color: var(--color-primary);
  border-color: var(--color-secondary);
}

.btn--primary:hover {
  background-color: #b8943e;
  border-color: #b8943e;
  box-shadow: 0 4px 14px rgba(201, 168, 76, 0.35);
}

.btn--outline {
  background-color: transparent;
  color: var(--color-white);
  border-color: var(--color-white);
}

.btn--outline:hover {
  background-color: var(--color-white);
  color: var(--color-primary);
}

.btn--outline-dark {
  background-color: transparent;
  color: var(--color-primary);
  border-color: var(--color-primary);
}

.btn--outline-dark:hover {
  background-color: var(--color-primary);
  color: var(--color-white);
}

.btn--lg {
  font-size: var(--font-size-base);
  padding: var(--space-4) var(--space-12);
}

.btn--sm {
  font-size: 0.75rem;
  padding: var(--space-2) var(--space-4);
}

.btn:disabled {
  opacity: 0.5;
  cursor: not-allowed;
  transform: none;
}

/* === COMPONENTE: CARD === */

.card {
  background-color: var(--color-white);
  border-radius: var(--border-radius-md);
  box-shadow: var(--shadow-sm);
  overflow: hidden;
  transition: transform var(--transition-base), box-shadow var(--transition-base);
}

.card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-md);
}

.card__media {
  aspect-ratio: 16 / 9;
  overflow: hidden;
}

.card__media img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform 0.4s ease;
}

.card:hover .card__media img {
  transform: scale(1.04);
}

.card__body {
  padding: var(--space-6);
}

.card__tag {
  display: inline-block;
  font-size: 0.7rem;
  font-weight: var(--font-weight-medium);
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--color-secondary);
  margin-bottom: var(--space-3);
}

.card__title {
  font-size: var(--font-size-lg);
  margin-bottom: var(--space-3);
}

.card__text {
  font-size: var(--font-size-sm);
  color: var(--color-text-muted);
  line-height: var(--line-height-base);
}

.card__footer {
  padding: var(--space-4) var(--space-6);
  border-top: 1px solid var(--color-border);
  display: flex;
  align-items: center;
  justify-content: space-between;
}

/* === COMPONENTE: SERVICIO ITEM === */

.service-item {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: var(--space-4);
  padding: var(--space-8);
  background-color: rgba(255, 255, 255, 0.04);
  border: 1px solid rgba(255, 255, 255, 0.1);
  border-radius: var(--border-radius-md);
  transition: background-color var(--transition-base), border-color var(--transition-base);
}

.service-item:hover {
  background-color: rgba(255, 255, 255, 0.08);
  border-color: var(--color-secondary);
}

.service-item__icon {
  width: 3rem;
  height: 3rem;
  display: flex;
  align-items: center;
  justify-content: center;
  background-color: var(--color-secondary);
  border-radius: var(--border-radius-sm);
  color: var(--color-primary);
  font-size: var(--font-size-xl);
  flex-shrink: 0;
}

.service-item__title {
  font-size: var(--font-size-lg);
  color: var(--color-white);
  margin-bottom: var(--space-2);
}

.service-item__text {
  font-size: var(--font-size-sm);
  color: rgba(255, 255, 255, 0.65);
  line-height: var(--line-height-base);
}

/* === COMPONENTE: EQUIPO === */

.team-member {
  text-align: center;
}

.team-member__photo {
  width: 10rem;
  height: 10rem;
  border-radius: 50%;
  object-fit: cover;
  margin-inline: auto;
  margin-bottom: var(--space-4);
  border: 3px solid var(--color-secondary);
  transition: transform var(--transition-base);
}

.team-member:hover .team-member__photo {
  transform: scale(1.04);
}

.team-member__name {
  font-size: var(--font-size-lg);
  margin-bottom: var(--space-1);
}

.team-member__role {
  font-size: var(--font-size-sm);
  color: var(--color-secondary);
  font-weight: var(--font-weight-medium);
  letter-spacing: 0.06em;
  text-transform: uppercase;
  margin-bottom: var(--space-3);
}

.team-member__bio {
  font-size: var(--font-size-sm);
  color: var(--color-text-muted);
  line-height: var(--line-height-base);
}

/* === COMPONENTE: FORMULARIO === */

.form {
  display: flex;
  flex-direction: column;
  gap: var(--space-6);
}

.form__row {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: var(--space-6);
}

.form__group {
  display: flex;
  flex-direction: column;
  gap: var(--space-2);
}

.form__label {
  font-size: var(--font-size-sm);
  font-weight: var(--font-weight-medium);
  color: var(--color-text);
  letter-spacing: 0.04em;
}

.form__input,
.form__textarea,
.form__select {
  width: 100%;
  padding: var(--space-3) var(--space-4);
  font-family: var(--font-body);
  font-size: var(--font-size-base);
  color: var(--color-text);
  background-color: var(--color-white);
  border: 1px solid var(--color-border);
  border-radius: var(--border-radius-sm);
  transition: border-color var(--transition-base), box-shadow var(--transition-base);
  outline: none;
}

.form__input:focus,
.form__textarea:focus,
.form__select:focus {
  border-color: var(--color-secondary);
  box-shadow: 0 0 0 3px rgba(201, 168, 76, 0.18);
}

.form__input::placeholder,
.form__textarea::placeholder {
  color: var(--color-text-muted);
}

.form__textarea {
  resize: vertical;
  min-height: 8rem;
}

.form__error {
  font-size: var(--font-size-sm);
  color: #d94f4f;
}

.form__input--error,
.form__textarea--error {
  border-color: #d94f4f;
}

.form__input--error:focus,
.form__textarea--error:focus {
  box-shadow: 0 0 0 3px rgba(217, 79, 79, 0.18);
}

.form__success {
  padding: var(--space-4) var(--space-6);
  background-color: rgba(52, 168, 83, 0.1);
  border: 1px solid rgba(52, 168, 83, 0.35);
  border-radius: var(--border-radius-sm);
  font-size: var(--font-size-sm);
  color: #2d7a47;
  text-align: center;
}

/* === COMPONENTE: FOOTER === */

.footer {
  background-color: var(--color-primary);
  color: rgba(255, 255, 255, 0.65);
  padding-block: var(--space-16);
}

.footer__grid {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr 1fr;
  gap: var(--space-12);
  margin-bottom: var(--space-12);
}

.footer__brand {
  display: flex;
  flex-direction: column;
  gap: var(--space-4);
}

.footer__logo {
  font-family: var(--font-heading);
  font-size: var(--font-size-xl);
  font-weight: var(--font-weight-bold);
  color: var(--color-white);
}

.footer__tagline {
  font-size: var(--font-size-sm);
  line-height: var(--line-height-base);
}

.footer__heading {
  font-family: var(--font-body);
  font-size: var(--font-size-sm);
  font-weight: var(--font-weight-bold);
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--color-white);
  margin-bottom: var(--space-4);
}

.footer__list {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: var(--space-3);
}

.footer__link {
  font-size: var(--font-size-sm);
  color: rgba(255, 255, 255, 0.55);
  transition: color var(--transition-base);
}

.footer__link:hover {
  color: var(--color-secondary);
}

.footer__bottom {
  padding-top: var(--space-8);
  border-top: 1px solid rgba(255, 255, 255, 0.1);
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: var(--space-4);
}

.footer__copy {
  font-size: var(--font-size-sm);
  color: rgba(255, 255, 255, 0.4);
}

.footer__social {
  display: flex;
  gap: var(--space-4);
}

.footer__social-link {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 2.25rem;
  height: 2.25rem;
  border-radius: 50%;
  border: 1px solid rgba(255, 255, 255, 0.2);
  color: rgba(255, 255, 255, 0.55);
  font-size: var(--font-size-sm);
  transition: border-color var(--transition-base),
              color var(--transition-base),
              background-color var(--transition-base);
}

.footer__social-link:hover {
  border-color: var(--color-secondary);
  color: var(--color-secondary);
  background-color: rgba(201, 168, 76, 0.08);
}

/* === COMPONENTE: LANG SWITCHER === */

.lang-switcher {
  display: flex;
  align-items: center;
  gap: var(--space-1);
}

.lang-switcher__btn {
  font-size: var(--font-size-sm);
  font-weight: var(--font-weight-medium);
  color: rgba(255, 255, 255, 0.55);
  padding: var(--space-1) var(--space-2);
  border-radius: var(--border-radius-sm);
  transition: color var(--transition-base), background-color var(--transition-base);
  cursor: pointer;
  background: none;
  border: none;
  font-family: var(--font-body);
}

.lang-switcher__btn:hover,
.lang-switcher__btn--active {
  color: var(--color-white);
  background-color: rgba(255, 255, 255, 0.1);
}

.lang-switcher__divider {
  color: rgba(255, 255, 255, 0.25);
  font-size: var(--font-size-sm);
  user-select: none;
}

/* === COMPONENTE: BADGE / TAG === */

.badge {
  display: inline-flex;
  align-items: center;
  font-size: 0.7rem;
  font-weight: var(--font-weight-medium);
  letter-spacing: 0.08em;
  text-transform: uppercase;
  padding: var(--space-1) var(--space-3);
  border-radius: var(--border-radius-lg);
  background-color: rgba(201, 168, 76, 0.15);
  color: var(--color-secondary);
  border: 1px solid rgba(201, 168, 76, 0.3);
}

/* === COMPONENTE: SEPARADOR DECORATIVO === */

.divider {
  width: 3rem;
  height: 3px;
  background-color: var(--color-secondary);
  border: none;
  border-radius: 2px;
  margin-block: var(--space-6);
}

.divider--center {
  margin-inline: auto;
}

/* === COMPONENTE: OVERLAY / MODAL === */

.overlay {
  position: fixed;
  inset: 0;
  background-color: var(--color-overlay);
  z-index: var(--z-overlay);
  display: flex;
  align-items: center;
  justify-content: center;
  opacity: 0;
  visibility: hidden;
  transition: opacity var(--transition-base), visibility var(--transition-base);
}

.overlay--visible {
  opacity: 1;
  visibility: visible;
}

.modal {
  position: relative;
  z-index: var(--z-modal);
  background-color: var(--color-white);
  border-radius: var(--border-radius-lg);
  box-shadow: var(--shadow-md);
  padding: var(--space-12);
  width: 90%;
  max-width: 36rem;
  max-height: 90svh;
  overflow-y: auto;
}

.modal__close {
  position: absolute;
  top: var(--space-4);
  right: var(--space-4);
  width: 2rem;
  height: 2rem;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 50%;
  color: var(--color-text-muted);
  transition: background-color var(--transition-base), color var(--transition-base);
}

.modal__close:hover {
  background-color: var(--color-bg);
  color: var(--color-text);
}

/* === COMPONENTE: SKIP LINK === */

.skip-link {
  position: absolute;
  top: -100%;
  left: var(--space-4);
  z-index: calc(var(--z-modal) + 10);
  background-color: var(--color-secondary);
  color: var(--color-primary);
  font-weight: var(--font-weight-bold);
  padding: var(--space-3) var(--space-6);
  border-radius: var(--border-radius-sm);
  transition: top var(--transition-base);
}

.skip-link:focus {
  top: var(--space-4);
}

