/* ----------------------------------------------------------
   BREAKPOINT: TABLET
   Aplica a viewports de 481px hasta 1024px
   ---------------------------------------------------------- */
@media (max-width: 1024px) {

    /* Navegación */
    .nav__menu {
        display: none;
    }

    .nav__hamburger {
        display: flex;
    }

    .nav__menu--open {
        display: flex;
        flex-direction: column;
    }

    /* Grid de servicios: 3-4 columnas → 2 columnas */
    .services__grid {
        grid-template-columns: repeat(2, 1fr);
    }

    /* Hero: reducir padding vertical */
    .hero {
        padding-top: 4rem;
        padding-bottom: 4rem;
    }

    /* Footer: columnas → 2 columnas */
    .footer__grid {
        grid-template-columns: repeat(2, 1fr);
    }

}

/* ----------------------------------------------------------
   BREAKPOINT: MÓVIL GRANDE / LANDSCAPE
   Aplica a viewports de 481px hasta 768px
   ---------------------------------------------------------- */
@media (max-width: 768px) {

    /* Tipografía: reducir tamaño de encabezados */
    .hero h1,
    .section h1 {
        font-size: 2rem;
        line-height: 1.2;
    }

    .section h2 {
        font-size: 1.6rem;
        line-height: 1.3;
    }

    .section h3 {
        font-size: 1.25rem;
        line-height: 1.4;
    }

    /* Sección Quiénes Somos: imagen arriba, texto abajo */
    .about__layout {
        flex-direction: column;
        grid-template-columns: 1fr;
    }

    .about__image {
        order: -1;
        width: 100%;
    }

    /* Formulario de contacto: campos a ancho completo */
    .contact__form input,
    .contact__form textarea,
    .contact__form select {
        width: 100%;
    }

    /* Grid de servicios: 2 columnas → 1 columna */
    .services__grid {
        grid-template-columns: 1fr;
    }

    /* Footer: 2 columnas → 1 columna */
    .footer__grid {
        grid-template-columns: 1fr;
    }

}

/* ----------------------------------------------------------
   BREAKPOINT: MÓVIL PEQUEÑO / PORTRAIT
   Aplica a viewports hasta 480px
   ---------------------------------------------------------- */
@media (max-width: 480px) {

    /* Tipografía: ajuste fino para pantallas pequeñas */
    .hero h1,
    .section h1 {
        font-size: 1.6rem;
        line-height: 1.2;
    }

    .section h2 {
        font-size: 1.35rem;
