}

document.addEventListener('DOMContentLoaded', function () {

  // ─── PASO 1: Leer configuración de idioma desde la URL ───────────────────
  var params = new URLSearchParams(window.location.search);
  var currentLang = params.get('lang') === 'en' ? 'en' : 'es';

  // ─── PASO 2: Menú hamburguesa ─────────────────────────────────────────────
  var menuToggle = document.getElementById('menu-toggle');
  var mainNav = document.getElementById('main-nav');

  if (menuToggle && mainNav) {
    menuToggle.addEventListener('click', function () {
      var isOpen = mainNav.classList.toggle('nav--open');
      menuToggle.setAttribute('aria-expanded', isOpen ? 'true' : 'false');
    });

    var navLinks = mainNav.querySelectorAll('a');
    navLinks.forEach(function (link) {
      link.addEventListener('click', function () {
        mainNav.classList.remove('nav--open');
        menuToggle.setAttribute('aria-expanded', 'false');
      });
    });
  }

  // ─── PASO 3: Scroll suave hacia anclas internas ───────────────────────────
  var anchorLinks = document.querySelectorAll('a[href^="#"]');
  anchorLinks.forEach(function (anchor) {
    anchor.addEventListener('click', function (e) {
      e.preventDefault();
      var targetId = anchor.getAttribute('href').slice(1);
      var targetEl = document.getElementById(targetId);
      if (targetEl) {
        targetEl.scrollIntoView({ behavior: 'smooth', block: 'start' });
      }
    });
  });

  // ─── PASO 4: Animaciones de entrada por scroll ────────────────────────────
  var animatedEls = document.querySelectorAll('.animate-on-scroll');
  if (animatedEls.length > 0) {
    var observer = new IntersectionObserver(function (entries, obs) {
      entries.forEach(function (entry) {
        if (entry.isIntersecting) {
          entry.target.classList.add('is-visible');
          obs.unobserve(entry.target);
        }
      });
    }, { threshold: 0.15 });

    animatedEls.forEach(function (el) {
      observer.observe(el);
    });
  }

  // ─── PASO 5: Marcar enlace de navegación activo ───────────────────────────
  var currentPath = window.location.pathname;
  if (mainNav) {
    var allNavLinks = mainNav.querySelectorAll('a');
    allNavLinks.forEach(function (link) {
      var linkHref = link.getAttribute('href');
      if (linkHref && (currentPath === linkHref || currentPath.endsWith(linkHref))) {
        link.classList.add('nav__link--active');
        link.setAttribute('aria-current', 'page');
      }
    });
  }

  // ─── PASO 6: Switcher de idioma ───────────────────────────────────────────
  function buildLangUrl(lang) {
    var base = window.location.pathname;
    return lang === 'en' ? base + '?lang=en' : base;
  }

  var langSwitcher = document.getElementById('lang-switcher');
  if (langSwitcher) {
    langSwitcher.textContent = currentLang === 'es' ? 'EN' : 'ES';

    langSwitcher.addEventListener('click', function (e) {
      e.preventDefault();
      var targetLang = currentLang === 'es' ? 'en' : 'es';
      window.location.href = buildLangUrl(targetLang);
    });
  }

});

document.addEventListener('DOMContentLoaded', function () {
  const form = document.getElementById('contact-form');
  const submitBtn = document.getElementById('submit-btn');
  const feedbackContainer = document.getElementById('form-feedback');

  if (!form || !submitBtn || !feedbackContainer) return;

  const FORMSPREE_ENDPOINT = window.AppConfig && window.AppConfig.FORMSPREE_ENDPOINT
    ? window.AppConfig.FORMSPREE_ENDPOINT
    : null;

  function sanitizeInput(value) {
    return value.trim();
  }

  function showFeedback(message, isError) {
    feedbackContainer.textContent = message;
    if (isError) {
      feedbackContainer.classList.add('feedback--error');
      feedbackContainer.classList.remove('feedback--success');
    } else {
      feedbackContainer.classList.add('feedback--success');
      feedbackContainer.classList.remove('feedback--error');
    }
    feedbackContainer.classList.remove('hidden');
  }

  function setLoadingState(isLoading) {
    if (isLoading) {
      submitBtn.disabled = true;
      submitBtn.textContent = 'Enviando...';
    } else {
      submitBtn.disabled = false;
      submitBtn.textContent = 'Enviar mensaje';
    }
  }

  function buildPayload(formData) {
    return {
      name: sanitizeInput(formData.get('name') || ''),
      email: sanitizeInput(formData.get('email') || ''),
      message: sanitizeInput(formData.get('message') || '')
    };
  }

  function handleContactSubmit(event) {
    event.preventDefault();

    if (!FORMSPREE_ENDPOINT) {
      showFeedback('Error de configuración. Contacta al administrador.', true);
      return;
    }

    setLoadingState(true);

    var payload = buildPayload(new FormData(event.target));
    var targetForm = event.target;

    fetch(FORMSPREE_ENDPOINT, {
      method: 'POST',
      headers: {
        'Accept': 'application/json',
        'Content-Type': 'application/json'
      },
      body: JSON.stringify(payload)
    })
      .then(function (response) {
        if (response.ok) {
          showFeedback('Mensaje enviado. Te contactaremos pronto.', false);
          targetForm.reset();
        } else {
          showFeedback('Error al enviar. Intenta nuevamente.', true);
        }
      })
      .catch(function () {
        showFeedback('Sin conexión. Verifica tu red e intenta de nuevo.', true);
      })
      .finally(function () {
        setLoadingState(false);
      });
  }

  form.addEventListener('submit', handleContactSubmit);
});
